const card=(title,concept,analogy,code,expected,pitfall,optional=false)=>({title,concept,analogy,code,expected,pitfall,optional});
const ex=(id,kind,title,prompt,setup,solution,expected,hints,explain,test)=>({id,kind,title,prompt,starter:setup+'\n# TODO：按照题目完成下面的处理\n',answer:setup+'\n'+solution,expected,hints,explain,test:test||`assert output.strip() == ${JSON.stringify(expected)}, "结果还不符合题目；检查数据、处理顺序和打印内容。"`});
