function lesson(id,track,chapter,title,lead,cards,tasks,quizzes,extra={}){const first=cards[0];return {id,track,chapter,title,short:title,stage:{numpy:'NumPy 数组',pandas:'Pandas 表格',matplotlib:'Matplotlib 画图',analysis:'数据综合实战'}[track],minutes:20,file:id.replaceAll('-','_')+'.py',lead,goals:['解释「'+first.title+'」的用途','运行并修改本章示例','完成基础题，再尝试综合练习'],concept:first.concept,analogy:first.analogy,code:first.code,expected:first.expected,pitfall:first.pitfall,cards:cards.slice(1),steps:['先运行示例，对照预期输出。','每次展开一个知识点，用「载入实验台」修改数据。','进入动手练习，先看提示，最后再看答案。'],summary:cards.map(c=>c.title+'：'+c.concept),diagram:['看清输入','选择操作','检查形状 / 类型','核对结果'],terms:track==='numpy'?['ndarray','shape','axis','广播']:track==='pandas'?['Series','DataFrame','索引','缺失值']:track==='matplotlib'?['Figure','Axes','Axis']:['向量化','DataFrame','Axes'],tasks,quizzes,sources:[source[track]],...extra};}
